const n=document.querySelector("#api-key"),t=document.querySelector("#key-status"),c=document.querySelector("#mic-status"),r=document.querySelector("#shortcut");async function i(){const e=await chrome.storage.local.get("geminiApiKey");t.textContent=typeof e.geminiApiKey=="string"&&e.geminiApiKey?"A key is saved locally.":"No key configured.";const o=await chrome.commands.getAll();r.textContent=o.find(a=>a.name==="toggle-recording")?.shortcut||"Not assigned"}document.querySelector("#save-key").addEventListener("click",async()=>{const e=n.value.trim();if(!e){t.textContent="Enter a key first.";return}await chrome.storage.local.set({geminiApiKey:e}),n.value="",t.textContent="Saved locally."});document.querySelector("#remove-key").addEventListener("click",async()=>{await chrome.storage.local.remove("geminiApiKey"),n.value="",t.textContent="Key removed."});document.querySelector("#enable-mic").addEventListener("click",async()=>{try{(await navigator.mediaDevices.getUserMedia({audio:!0})).getTracks().forEach(o=>o.stop()),c.textContent="Microphone enabled. You can record from ChatGPT now."}catch{c.textContent="Microphone access was denied. Allow it in Chrome site settings and try again."}});document.querySelector("#change-shortcut").addEventListener("click",()=>{chrome.tabs.create({url:"chrome://extensions/shortcuts"})});i();
